def lin_fit2(basis_eps, tb):
    X=np.column_stack([be*tt for be in basis_eps for tt in tb])
    coef,*_=np.linalg.lstsq(X,sigma,rcond=None)
    r=sigma-X@coef
    return np.mean(r**2)/np.var(sigma), coef
